11	// 本文件回归“保存时同一学生名下的同一项要求不得同时有两份有效免修”。正常
12	// 申请流程（ApplyWaiver）与读取记录文件（Load）都拒绝这类冲突，但调用方
13	// 取得免修记录后可以直接修改其内容——把另一份申请改成有效，或把一份有效
14	// 申请的目标改到已由免修满足的要求——因此用例先经公开接口建立结构完整的
15	// 记录，再直接改免修状态或目标要求，聚焦 Save 这一路径：
16	//   - 同一学生、同一要求下两份不同编号的有效免修（依据相同也算两份；该要求
17	//     另有通过修读也不能掩盖；冲突申请之间夹着其他合法历史结果一样），整次
18	//     保存必须拒绝：错误说明是有效免修冲突，并点名目标文件、所属学生、要求
19	//     编号与冲突的两份免修编号；
20	//   - 目标文件原本不存在时不创建记录文件，也不残留临时文件；已有文件的全部
21	//     字节原样保留、仍可正常读取与核对；
22	//   - 待保存的内存记录保持提交时的内容：不删申请、不替调用方选定有效免修、
23	//     不改状态/目标要求/依据；调用方消除冲突后可继续用原有保存功能；
24	//   - 冲突只按（所属学生、目标要求）完整编号判定：编号前后有空白的是不同
25	//     要求；不同学生各自拥有同号要求、同号免修合法；同一学生的不同要求各有
26	//     一份有效免修合法；一份有效免修与已拒绝、已撤销历史共存合法。
27	
28	// saveWaiverStore 建立两名学生、两门课程与各自要求，供用例登记免修后再改出
29	// 有效免修冲突：s1 名下有要求 r1（课程 c1）与 r2（课程 c2），s2 名下有同号
30	// 要求 r1（课程 c2）。
31	func saveWaiverStore(t *testing.T) *Store {
32		t.Helper()
33		s := NewStore()
34		mustStudent(t, s, "s1")
35		mustStudent(t, s, "s2")
36		mustCourse(t, s, "c1", "高等数学", 4)
37		mustCourse(t, s, "c2", "线性代数", 3)
38		mustReq(t, s, "s1", "r1", "c1")
39		mustReq(t, s, "s1", "r2", "c2")
40		mustReq(t, s, "s2", "r1", "c2")
41		return s
42	}
43	
44	// mustWaiver 经公开接口提交免修申请并断言得到的状态。
45	func mustWaiver(t *testing.T, s *Store, student, req, id, basis string, want WaiverStatus) *Waiver {
46		t.Helper()
47		w, a, err := s.ApplyWaiver(student, req, id, basis)
48		if err != nil || a != ActionCreated {
49			t.Fatalf("ApplyWaiver(%q,%q,%q) = action %v, err %v", student, req, id, a, err)
50		}
51		if w.Status != want {
52			t.Fatalf("免修 %s 状态应为 %s，得到 %s", id, want, w.Status)
53		}
54		return w
55	}
56	
57	// assertSaveWaiverConflictError 断言保存错误说明是有效免修冲突，并点名目标
58	// 文件、所属学生、要求编号与冲突的两份免修编号，返回解析后的类型化错误。
59	func assertSaveWaiverConflictError(t *testing.T, err error, path,
60		student, req, first, second string) *duplicateApprovedWaiverError {
61		t.Helper()
62		if err == nil {
63			t.Fatalf("学生 %s 的要求 %s 有两份有效免修 %s 与 %s 时必须拒绝保存",
64				student, req, first, second)
65		}
66		var dwe *duplicateApprovedWaiverError
67		if !errors.As(err, &dwe) {
68			t.Fatalf("应返回 *duplicateApprovedWaiverError，得到 %T：%v", err, err)
69		}
70		if dwe.student != student || dwe.req != req ||
71			dwe.first != first || dwe.second != second {
72			t.Fatalf("类型化错误定位不符：应为 (%s,%s) 的 %s 与 %s，得到 %+v",
73				student, req, first, second, dwe)
74		}
75		msg := err.Error()
76		for _, want := range []string{path, "有效免修", student, req, first, second} {
77			if !strings.Contains(msg, want) {
78				t.Fatalf("错误应说明有效免修冲突并点名目标文件、学生、要求与双方（缺 %q），得到：%v",
79					want, err)
80			}
81		}
82		return dwe
83	}
84	
85	// assertNoFileLeftBehind 断言目标文件未创建且目录下没有残留临时文件。
86	func assertNoFileLeftBehind(t *testing.T, path string) {
87		t.Helper()
88		if _, statErr := os.Stat(path); !os.IsNotExist(statErr) {
89			t.Fatalf("拒绝保存后不得创建记录文件，stat err=%v", statErr)
90		}
91		leftover, _ := filepath.Glob(filepath.Join(filepath.Dir(path), ".credit-*.tmp"))
92		if len(leftover) != 0 {
93			t.Fatalf("拒绝保存后不得残留临时文件：%v", leftover)
94		}
95	}
96	
97	// TestSaveRejectsDuplicateApprovedWaiver 覆盖各类“同一要求两份有效免修”的
98	// 组合：改状态生效、改目标要求、依据相同、另有通过修读、夹着合法历史，结论
99	// 都是整次拒绝保存。
100	func TestSaveRejectsDuplicateApprovedWaiver(t *testing.T) {
101		t.Run("把另一份申请改成有效", func(t *testing.T) {
102			s := saveWaiverStore(t)
103			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
104			// 第二份申请因已有有效免修被正常拒绝，随后调用方直接把它改成有效。
105			w2 := mustWaiver(t, s, "s1", "r1", "w2", "课程已修过", WaiverRejected)
106			w2.Status = WaiverApproved
107	
108			path := filepath.Join(t.TempDir(), "records.json")
109			err := s.Save(path)
110			assertSaveWaiverConflictError(t, err, path, "s1", "r1", "w1", "w2")
111			assertNoFileLeftBehind(t, path)
112		})
113	
114		t.Run("把有效申请的目标改到已由免修满足的要求", func(t *testing.T) {
115			s := saveWaiverStore(t)
116			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
117			w2 := mustWaiver(t, s, "s1", "r2", "w2", "课程已修过", WaiverApproved)
118			// 调用方把 w2 的目标从 r2 改到已有有效免修的 r1。
119			w2.ReqID = "r1"
120	
121			path := filepath.Join(t.TempDir(), "records.json")
122			err := s.Save(path)
123			assertSaveWaiverConflictError(t, err, path, "s1", "r1", "w1", "w2")
124			assertNoFileLeftBehind(t, path)
125		})
126	
127		t.Run("两份申请依据相同仍算两份", func(t *testing.T) {
128			s := saveWaiverStore(t)
129			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
130			w2 := mustWaiver(t, s, "s1", "r1", "w2", "竞赛获奖", WaiverRejected)
131			w2.Status = WaiverApproved
132	
133			path := filepath.Join(t.TempDir(), "records.json")
134			err := s.Save(path)
135			assertSaveWaiverConflictError(t, err, path, "s1", "r1", "w1", "w2")
136		})
137	
138		t.Run("该要求另有通过修读也不能掩盖冲突", func(t *testing.T) {
139			s := saveWaiverStore(t)
140			mustEnroll(t, s, "s1", "r1", "2024春", "e1")
141			if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
142				t.Fatal(err)
143			}
144			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
145			w2 := mustWaiver(t, s, "s1", "r1", "w2", "课程已修过", WaiverRejected)
146			w2.Status = WaiverApproved
147	
148			path := filepath.Join(t.TempDir(), "records.json")
149			err := s.Save(path)
150			assertSaveWaiverConflictError(t, err, path, "s1", "r1", "w1", "w2")
151		})
152	
153		t.Run("冲突申请之间夹着其他合法历史", func(t *testing.T) {
154			s := saveWaiverStore(t)
155			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
156			// 中间隔着：r1 的又一份被拒绝申请、r2 的有效免修、其他学生的有效免修。
157			mustWaiver(t, s, "s1", "r1", "w9", "重复申请", WaiverRejected)
158			mustWaiver(t, s, "s1", "r2", "w3", "课程已修过", WaiverApproved)
159			mustWaiver(t, s, "s2", "r1", "w1", "竞赛获奖", WaiverApproved)
160			w2 := mustWaiver(t, s, "s1", "r1", "w2", "另一依据", WaiverRejected)
161			w2.Status = WaiverApproved
162	
163			path := filepath.Join(t.TempDir(), "records.json")
164			err := s.Save(path)
165			// 报错仍按记录先后点名最先相撞的一对：s1/r1 的 w1 与 w2。
166			assertSaveWaiverConflictError(t, err, path, "s1", "r1", "w1", "w2")
167			assertNoFileLeftBehind(t, path)
168		})
169	}
170	
171	// TestSaveWaiverConflictKeepsExistingFileUntouched 目标文件已存在且内容完好
172	// 时，含有效免修冲突的保存必须失败：原文件逐字节保留、仍可读取核对；冲突的
173	// 内存记录保持提交时的内容；调用方自行消除冲突后可继续正常保存。
174	func TestSaveWaiverConflictKeepsExistingFileUntouched(t *testing.T) {
175		dir := t.TempDir()
176		path := filepath.Join(dir, "records.json")
177	
178		// 先落一份完好文件：s1 的 r1 由有效免修 w1 满足（4 学分），r2 未满足。
179		good := saveWaiverStore(t)
180		mustWaiver(t, good, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
181		if err := good.Save(path); err != nil {
182			t.Fatalf("前置正常保存失败：%v", err)
183		}
184		raw, err := os.ReadFile(path)
185		if err != nil {
186			t.Fatal(err)
187		}
188	
189		// 程序重新取得这份记录，再提交 w2（被正常拒绝）并直接把它改成有效。
190		loaded, existed, err := Load(path)
191		if err != nil || !existed {
192			t.Fatalf("前置文件应正常读取：existed=%v err=%v", existed, err)
193		}
194		w2 := mustWaiver(t, loaded, "s1", "r1", "w2", "课程已修过", WaiverRejected)
195		w2.Status = WaiverApproved
196		saveErr := loaded.Save(path)
197		assertSaveWaiverConflictError(t, saveErr, path, "s1", "r1", "w1", "w2")
198	
199		got, err := os.ReadFile(path)
200		if err != nil {
201			t.Fatalf("原文件应继续可读：%v", err)
202		}
203		if string(got) != string(raw) {
204			t.Fatalf("拒绝保存后已有文件必须逐字节保持原样\nwant=%q\n got=%q", raw, got)
205		}
206		leftover, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp"))
207		if len(leftover) != 0 {
208			t.Fatalf("拒绝保存后不得残留临时文件：%v", leftover)
209		}
210	
211		// 原文件仍可正常读取与核对：s1 凭 w1 得 4 学分，文件中没有 w2。
212		reloaded, existed, err := Load(path)
213		if err != nil || !existed {
214			t.Fatalf("原文件应仍可正常读取：existed=%v err=%v", existed, err)
215		}
216		rep := reloaded.CheckStudent("s1")
217		if rep.TotalCredits != 4 || rep.Requirements[0].Source != "waiver" ||
218			rep.Requirements[0].WaiverID != "w1" {
219			t.Fatalf("原文件核对结果应保持不变，得到 %+v", rep)
220		}
221		if w := reloaded.Waiver("s1", "w2"); w != nil {
222			t.Fatalf("坏记录不得落盘，原文件中不应出现 w2，得到 %+v", w)
223		}
224	
225		// 内存中的冲突记录保持提交时的内容：两份申请都在，状态、目标、依据不改。
226		w1 := loaded.Waiver("s1", "w1")
227		if w1 == nil || w1.Status != WaiverApproved || w1.ReqID != "r1" || w1.Basis != "竞赛获奖" {
228			t.Fatalf("w1 不得被改动，得到 %+v", w1)
229		}
230		if w2 := loaded.Waiver("s1", "w2"); w2 == nil || w2.Status != WaiverApproved ||
231			w2.ReqID != "r1" || w2.Basis != "课程已修过" {
232			t.Fatalf("w2 应保持调用方改成的样子，保存功能不得代为选定或改回，得到 %+v", w2)
233		}
234		if n := len(loaded.Waivers("s1")); n != 2 {
235			t.Fatalf("不得删除任何免修申请，得到 %d 条", n)
236		}
237	
238		// 由调用方自行消除冲突（撤销 w2）后，同一路径即可正常保存。
239		w2.Status = WaiverRevoked
240		if err := loaded.Save(path); err != nil {
241			t.Fatalf("调用方消除冲突后应能正常保存：%v", err)
242		}
243		final, _, err := Load(path)
244		if err != nil {
245			t.Fatalf("消除冲突后的文件应可正常读取：%v", err)
246		}
247		if w := final.Waiver("s1", "w2"); w == nil || w.Status != WaiverRevoked {
248			t.Fatalf("消除冲突后的修改应原样落盘，得到 %+v", w)
249		}
250	}
251	
252	// TestSaveWaiverConflictDoesNotMutateMemory 拒绝保存不得改动待保存内存记录的
253	// 任何内容：两份冲突申请、其他有效免修、被拒绝/已撤销历史都保持提交时的样子。
254	func TestSaveWaiverConflictDoesNotMutateMemory(t *testing.T) {
255		s := saveWaiverStore(t)
256		mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
257		mustWaiver(t, s, "s1", "r2", "w3", "课程已修过", WaiverApproved)
258		w2 := mustWaiver(t, s, "s1", "r1", "w2", "另一依据", WaiverRejected)
259		w2.Status = WaiverApproved
260		// 其他学生的合法历史与一条已撤销历史也不受影响。
261		mustWaiver(t, s, "s2", "r1", "w1", "竞赛获奖", WaiverApproved)
262		if _, _, err := s.RevokeWaiver("s2", "w1", "材料作废"); err != nil {
263			t.Fatal(err)
264		}
265	
266		path := filepath.Join(t.TempDir(), "records.json")
267		if err := s.Save(path); err == nil {
268			t.Fatal("同一要求有两份有效免修时必须拒绝保存")
269		}
270	
271		for id, want := range map[string]WaiverStatus{
272			"w1": WaiverApproved, "w2": WaiverApproved, "w3": WaiverApproved,
273		} {
274			w := s.Waiver("s1", id)
275			if w == nil || w.Status != want {
276				t.Fatalf("s1 的免修 %s 应保持状态 %s，得到 %+v", id, want, w)
277			}
278		}
279		if w := s.Waiver("s1", "w2"); w.ReqID != "r1" || w.Basis != "另一依据" {
280			t.Fatalf("w2 的目标要求与依据不得被改动，得到 %+v", w)
281		}
282		if w := s.Waiver("s2", "w1"); w == nil || w.Status != WaiverRevoked || w.Reason != "材料作废" {
283			t.Fatalf("s2 的已撤销历史不得被改动，得到 %+v", w)
284		}
285		if n := len(s.waivers); n != 4 {
286			t.Fatalf("不得删除任何免修记录，得到 %d 条", n)
287		}
288	}
289	
290	// TestSaveLegalWaiverArrangementsAccepted 合法的免修安排继续正常保存，学分与
291	// 来源规则保持不变：
292	//   - 不同学生各自拥有同号要求、同号免修；
293	//   - 同一学生的不同要求各有一份有效免修；
294	//   - 编号前后有空白的是不同要求，各自的有效免修互不冲突；
295	//   - 一份有效免修与已拒绝、已撤销历史共存，失效申请不占有效名额；
296	//   - 同一要求只计一份学分，有效免修说明当前来源，修读历史继续保留。
297	func TestSaveLegalWaiverArrangementsAccepted(t *testing.T) {
298		t.Run("不同学生同号要求同号免修", func(t *testing.T) {
299			s := saveWaiverStore(t)
300			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
301			mustWaiver(t, s, "s2", "r1", "w1", "竞赛获奖", WaiverApproved)
302	
303			path := filepath.Join(t.TempDir(), "records.json")
304			if err := s.Save(path); err != nil {
305				t.Fatalf("不同学生各自的同号有效免修应正常保存：%v", err)
306			}
307			loaded, _, err := Load(path)
308			if err != nil {
309				t.Fatalf("合法记录保存后应可读取：%v", err)
310			}
311			if rep := loaded.CheckStudent("s1"); rep.TotalCredits != 4 ||
312				rep.Requirements[0].WaiverID != "w1" {
313				t.Fatalf("s1 应凭本人 w1 得 4 学分，得到 %+v", rep)
314			}
315			if rep := loaded.CheckStudent("s2"); rep.TotalCredits != 3 ||
316				rep.Requirements[0].WaiverID != "w1" {
317				t.Fatalf("s2 应凭本人 w1 得 3 学分，得到 %+v", rep)
318			}
319			if loaded.Waiver("s1", "w1") == loaded.Waiver("s2", "w1") {
320				t.Fatal("两名学生的同号免修应仍是两条独立记录")
321			}
322		})
323	
324		t.Run("同一学生不同要求各有一份有效免修", func(t *testing.T) {
325			s := saveWaiverStore(t)
326			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
327			mustWaiver(t, s, "s1", "r2", "w2", "课程已修过", WaiverApproved)
328	
329			path := filepath.Join(t.TempDir(), "records.json")
330			if err := s.Save(path); err != nil {
331				t.Fatalf("不同要求各有一份有效免修应正常保存：%v", err)
332			}
333			loaded, _, err := Load(path)
334			if err != nil {
335				t.Fatalf("合法记录保存后应可读取：%v", err)
336			}
337			if rep := loaded.CheckStudent("s1"); rep.TotalCredits != 7 || len(rep.Unmet) != 0 {
338				t.Fatalf("两项要求应各计一份学分共 7 学分，得到 %+v", rep)
339			}
340		})
341	
342		t.Run("编号前后有空白的是不同要求", func(t *testing.T) {
343			s := NewStore()
344			mustStudent(t, s, "s1")
345			mustCourse(t, s, "c1", "高等数学", 4)
346			mustCourse(t, s, "c2", "线性代数", 3)
347			mustReq(t, s, "s1", "r1", "c1")
348			mustReq(t, s, "s1", " r1 ", "c2")
349			// “r1”与“ r1 ”是两项不同要求，各自的有效免修互不冲突。
350			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
351			mustWaiver(t, s, "s1", " r1 ", "w2", "课程已修过", WaiverApproved)
352	
353			path := filepath.Join(t.TempDir(), "records.json")
354			if err := s.Save(path); err != nil {
355				t.Fatalf("带空白编号的不同要求各有有效免修应正常保存：%v", err)
356			}
357			loaded, _, err := Load(path)
358			if err != nil {
359				t.Fatalf("合法记录保存后应可读取：%v", err)
360			}
361			if rep := loaded.CheckStudent("s1"); rep.TotalCredits != 7 {
362				t.Fatalf("两项不同要求应各计一份学分共 7 学分，得到 %+v", rep)
363			}
364			if loaded.Waiver("s1", "w1").ReqID != "r1" || loaded.Waiver("s1", "w2").ReqID != " r1 " {
365				t.Fatal("编号原文不得因保存被修剪或合并")
366			}
367		})
368	
369		t.Run("有效免修与已拒绝已撤销历史共存", func(t *testing.T) {
370			s := saveWaiverStore(t)
371			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
372			// 同一要求下：一份被正常拒绝的申请与一份已撤销的旧申请，都不占有效名额。
373			mustWaiver(t, s, "s1", "r1", "w2", "重复申请", WaiverRejected)
374			w0 := mustWaiver(t, s, "s1", "r2", "w0", "旧依据", WaiverApproved)
375			if _, _, err := s.RevokeWaiver("s1", "w0", "材料作废"); err != nil {
376				t.Fatal(err)
377			}
378			w0.ReqID = "r1" // 调用方把已撤销申请的目标改到 r1：失效历史不占有效名额。
379	
380			path := filepath.Join(t.TempDir(), "records.json")
381			if err := s.Save(path); err != nil {
382				t.Fatalf("失效申请不占有效名额，应正常保存：%v", err)
383			}
384			loaded, _, err := Load(path)
385			if err != nil {
386				t.Fatalf("合法记录保存后应可读取：%v", err)
387			}
388			// 所有历史按原内容保留；r1 仍由唯一的有效免修 w1 满足，只计一份学分。
389			rep := loaded.CheckStudent("s1")
390			if rep.TotalCredits != 4 || rep.Requirements[0].WaiverID != "w1" {
391				t.Fatalf("r1 应凭 w1 计 4 学分，得到 %+v", rep)
392			}
393			if len(rep.RejectedWaivers) != 1 || rep.RejectedWaivers[0].Waiver.ID != "w2" {
394				t.Fatalf("被拒绝历史应原样保留，得到 %+v", rep.RejectedWaivers)
395			}
396			if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "w0" {
397				t.Fatalf("已撤销历史应原样保留，得到 %v", rep.RevokedWaivers)
398			}
399		})
400	
401		t.Run("同一要求只计一份学分_免修说明来源_修读历史保留", func(t *testing.T) {
402			s := saveWaiverStore(t)
403			mustEnroll(t, s, "s1", "r1", "2024春", "e1")
404			if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
405				t.Fatal(err)
406			}
407			mustWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", WaiverApproved)
408	
409			path := filepath.Join(t.TempDir(), "records.json")
410			if err := s.Save(path); err != nil {
411				t.Fatalf("通过修读与一份有效免修并存应正常保存：%v", err)
412			}
413			loaded, _, err := Load(path)
414			if err != nil {
415				t.Fatalf("合法记录保存后应可读取：%v", err)
416			}
417			rep := loaded.CheckStudent("s1")
418			if rep.TotalCredits != 4 {
419				t.Fatalf("同一要求只计一份 4 学分，得到 %d", rep.TotalCredits)
420			}
421			st := rep.Requirements[0]
422			if st.Source != "waiver" || st.WaiverID != "w1" ||
423				len(st.PassedEnrollmentIDs) != 1 || st.PassedEnrollmentIDs[0] != "e1" {
424				t.Fatalf("有效免修应说明来源且修读历史保留，得到 %+v", st)
425			}
426		})
427	}
