14	// 新申请记为已拒绝），它来自“直接使用课程记录功能的程序取得记录后修改了
15	// 免修内容”：本用例就模拟这样的程序——通过 credit 包的公开接口取得免修、
16	// 把另一份申请改成有效或改目标要求，再调用保存功能。保存功能必须：
17	//   - 直接返回错误：说明是有效免修冲突，并点名目标记录文件、所属学生、要求
18	//     编号与冲突的两份免修编号，不把可用文件替换成随后被判损坏的文件；
19	//   - 目标原本不存在时不创建记录文件、不残留临时文件；已有文件全部字节原样
20	//     保留，命令行仍能正常读取与核对；
21	//   - 待保存内存记录保持提交时的内容，程序可自行消除冲突后再保存；
22	//   - 不同学生各自的同号有效免修、同一学生不同要求各一份有效免修照常保存。
23	
24	// newWaiverProgramStore 像直接调用记录功能的程序一样建立记录：s1 名下有要求
25	// r1（4 学分课程 c1）与 r2（3 学分课程 c2），s2 名下有同号要求 r1（c2）。
26	func newWaiverProgramStore(t *testing.T) *credit.Store {
27		t.Helper()
28		s := credit.NewStore()
29		for _, step := range []func() error{
30			func() error { _, _, e := s.AddStudent("s1"); return e },
31			func() error { _, _, e := s.AddStudent("s2"); return e },
32			func() error { _, _, e := s.AddCourse("c1", "高等数学", 4); return e },
33			func() error { _, _, e := s.AddCourse("c2", "线性代数", 3); return e },
34			func() error { _, _, e := s.AddRequirement("s1", "r1", "c1"); return e },
35			func() error { _, _, e := s.AddRequirement("s1", "r2", "c2"); return e },
36			func() error { _, _, e := s.AddRequirement("s2", "r1", "c2"); return e },
37		} {
38			if err := step(); err != nil {
39				t.Fatalf("构造前置记录失败：%v", err)
40			}
41		}
42		return s
43	}
44	
45	// mustProgramWaiver 经公开接口提交免修申请并断言得到的状态。
46	func mustProgramWaiver(t *testing.T, s *credit.Store, student, req, id, basis string,
47		want credit.WaiverStatus) *credit.Waiver {
48		t.Helper()
49		w, _, err := s.ApplyWaiver(student, req, id, basis)
50		if err != nil {
51			t.Fatalf("ApplyWaiver(%q,%q,%q) 失败：%v", student, req, id, err)
52		}
53		if w.Status != want {
54			t.Fatalf("免修 %s 状态应为 %s，得到 %s", id, want, w.Status)
55		}
56		return w
57	}
58	
59	// TestProgramSaveDuplicateApprovedWaiverNotCreated 模拟直接调用记录功能的程序：
60	// 目标文件原本不存在，程序把 s1/r1 上被正常拒绝的 w2 直接改成有效后保存，
61	// 必须收到错误，错误说明有效免修冲突并点名目标文件、学生 s1、要求 r1 与
62	// 冲突的 w1、w2；不创建记录文件，也不残留临时文件。随后命令行访问该路径应
63	// 视为无记录，而不是读到损坏文件。
64	func TestProgramSaveDuplicateApprovedWaiverNotCreated(t *testing.T) {
65		s := newWaiverProgramStore(t)
66		mustProgramWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", credit.WaiverApproved)
67		// 第二份申请被正常拒绝并记入历史，程序取得记录后直接把它改成有效。
68		w2 := mustProgramWaiver(t, s, "s1", "r1", "w2", "课程已修过", credit.WaiverRejected)
69		w2.Status = credit.WaiverApproved
70	
71		dir := t.TempDir()
72		file := filepath.Join(dir, "records.json")
73		err := s.Save(file)
74		if err == nil {
75			t.Fatal("同一要求有两份有效免修 w1 与 w2 时必须拒绝保存")
76		}
77		msg := err.Error()
78		for _, want := range []string{file, "有效免修", "s1", "r1", "w1", "w2"} {
79			if !strings.Contains(msg, want) {
80				t.Fatalf("保存错误应说明有效免修冲突并点名目标文件、学生、要求与双方（缺 %q），得到：%v",
81					want, err)
82			}
83		}
84		if _, statErr := os.Stat(file); !os.IsNotExist(statErr) {
85			t.Fatalf("拒绝保存后不得创建记录文件，stat err=%v", statErr)
86		}
87		leftover, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp"))
88		if len(leftover) != 0 {
89			t.Fatalf("拒绝保存后不得残留临时文件：%v", leftover)
90		}
91	
92		// 命令行随后访问该路径：文件仍不存在，按“学生不存在”的业务规则退出码 1，
93		// 绝不能读到一份损坏文件（退出码 2）。
94		out, errText, code := runCLI(t, file, "check", "s1")
95		if code != exitRejected {
96			t.Fatalf("文件未创建时应按无记录处理（退出码 %d），code=%d out=%q err=%q",
97				exitRejected, code, out, errText)
98		}
99		if strings.Contains(errText, "内容损坏") {
100			t.Fatalf("拒绝保存不得留下损坏文件，err=%q", errText)
101		}
102	
103		// 内存记录保持提交时的内容：两份申请都在，程序可自行消除冲突后再保存。
104		if w := s.Waiver("s1", "w1"); w == nil || w.Status != credit.WaiverApproved {
105			t.Fatalf("w1 应保持有效，得到 %+v", w)
106		}
107		if w := s.Waiver("s1", "w2"); w == nil || w.Status != credit.WaiverApproved ||
108			w.ReqID != "r1" || w.Basis != "课程已修过" {
109			t.Fatalf("w2 应保持程序改成的样子，保存功能不得代为选定或改回，得到 %+v", w)
110		}
111		if n := len(s.Waivers("s1")); n != 2 {
112			t.Fatalf("不得删除 s1 的免修申请，得到 %d 条", n)
113		}
114		w2.Status = credit.WaiverRevoked
115		if err := s.Save(file); err != nil {
116			t.Fatalf("程序消除冲突后应能正常保存：%v", err)
117		}
118	}
119	
120	// TestProgramSaveDuplicateApprovedWaiverKeepsUsableFile 目标文件已存在且完好
121	// 时，程序取得记录后改出有效免修冲突再保存到同一路径：保存失败，已有文件
122	// 全部字节原样保留，命令行仍能正常读取与核对，绝不会把可用文件替换成损坏
123	// 文件。
124	func TestProgramSaveDuplicateApprovedWaiverKeepsUsableFile(t *testing.T) {
125		dir := t.TempDir()
126		file := filepath.Join(dir, "records.json")
127	
128		// 先落一份完好文件：s1 的 r1 由有效免修 w1 满足（4 学分），r2 未满足。
129		good := newWaiverProgramStore(t)
130		mustProgramWaiver(t, good, "s1", "r1", "w1", "竞赛获奖", credit.WaiverApproved)
131		if err := good.Save(file); err != nil {
132			t.Fatalf("前置正常保存失败：%v", err)
133		}
134		raw, err := os.ReadFile(file)
135		if err != nil {
136			t.Fatal(err)
137		}
138	
139		// 程序重新取得这份记录，把 r2 的有效免修 w2 的目标改到已有有效免修的 r1。
140		loaded, existed, err := credit.Load(file)
141		if err != nil || !existed {
142			t.Fatalf("前置文件应正常读取：existed=%v err=%v", existed, err)
143		}
144		w2 := mustProgramWaiver(t, loaded, "s1", "r2", "w2", "课程已修过", credit.WaiverApproved)
145		w2.ReqID = "r1"
146		saveErr := loaded.Save(file)
147		if saveErr == nil {
148			t.Fatal("把有效免修目标改到已由免修满足的要求后保存必须失败")
149		}
150		for _, want := range []string{file, "有效免修", "s1", "r1", "w1", "w2"} {
151			if !strings.Contains(saveErr.Error(), want) {
152				t.Fatalf("保存错误应说明有效免修冲突并点名目标文件、学生、要求与双方（缺 %q），得到：%v",
153					want, saveErr)
154			}
155		}
156	
157		got, err := os.ReadFile(file)
158		if err != nil {
159			t.Fatalf("原文件应继续可读：%v", err)
160		}
161		if string(got) != string(raw) {
162			t.Fatalf("拒绝保存后已有文件必须逐字节保持原样\nwant=%q\n got=%q", raw, got)
163		}
164		leftover, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp"))
165		if len(leftover) != 0 {
166			t.Fatalf("拒绝保存后不得残留临时文件：%v", leftover)
167		}
168	
169		// 命令行仍能正常读取旧文件：s1 凭 w1 得 4 学分；w2 没有落盘。
170		out, _, code := runCLI(t, file, "check", "s1")
171		if code != exitOK || !strings.Contains(out, "总学分：4") ||
172			!strings.Contains(out, "来源为有效免修 w1") {
173			t.Fatalf("旧文件中 s1 的核对结果应保持不变，code=%d out=%q", code, out)
174		}
175		if strings.Contains(out, "w2") {
176			t.Fatalf("坏记录不得落盘，旧文件中不应出现 w2，out=%q", out)
177		}
178	}
179	
180	// TestProgramSaveLegalWaiverArrangementsStillWorks 合法免修安排经直接调用保存
181	// 功能仍正常落盘并可被命令行读取：不同学生各自的同号有效免修、同一学生不同
182	// 要求各一份有效免修、有效免修与已拒绝/已撤销历史共存。
183	func TestProgramSaveLegalWaiverArrangementsStillWorks(t *testing.T) {
184		s := newWaiverProgramStore(t)
185		mustProgramWaiver(t, s, "s1", "r1", "w1", "竞赛获奖", credit.WaiverApproved)
186		mustProgramWaiver(t, s, "s1", "r2", "w2", "课程已修过", credit.WaiverApproved)
187		// s2 的同号要求、同号免修是另一名学生的合法记录。
188		mustProgramWaiver(t, s, "s2", "r1", "w1", "竞赛获奖", credit.WaiverApproved)
189		// s1/r1 上再留一份被正常拒绝的申请：失效历史不占有效名额。
190		mustProgramWaiver(t, s, "s1", "r1", "w9", "重复申请", credit.WaiverRejected)
191	
192		file := filepath.Join(t.TempDir(), "records.json")
193		if err := s.Save(file); err != nil {
194			t.Fatalf("合法免修安排应正常保存：%v", err)
195		}
196		leftover, _ := filepath.Glob(filepath.Join(filepath.Dir(file), ".credit-*.tmp"))
197		if len(leftover) != 0 {
198			t.Fatalf("正常保存不应残留临时文件：%v", leftover)
199		}
200	
201		// 命令行正常读取：s1 两项要求各计一份共 7 学分；s2 凭本人 w1 得 3 学分。
202		out, _, code := runCLI(t, file, "check", "s1")
203		if code != exitOK || !strings.Contains(out, "总学分：7") ||
204			!strings.Contains(out, "来源为有效免修 w1") ||
205			!strings.Contains(out, "来源为有效免修 w2") {
206			t.Fatalf("s1 核对结果应保持，code=%d out=%q", code, out)
207		}
208		out, _, code = runCLI(t, file, "check", "s2")
209		if code != exitOK || !strings.Contains(out, "总学分：3") ||
210			!strings.Contains(out, "来源为有效免修 w1") {
211			t.Fatalf("s2 应凭本人 w1 得 3 学分，code=%d out=%q", code, out)
212		}
213	}
