// 内存记录保持提交时的内容；调用方自行修正归属后可继续正常保存。
func TestSaveWaiverOwnershipKeepsExistingFileUntouched(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "records.json")

	// 先落一份完好文件：s1 的 r1 由有效免修 w1 满足（4 学分），r2 未满足。
